import argparse


def parse_args():
    parser = argparse.ArgumentParser(description="Causal Dialog Route Reranker")
    parser.add_argument("--id", type=str, default="causal_dialog_route_reranker")
    parser.add_argument("--seed", type=int, default=0)
    parser.add_argument("--world_size", type=int, default=1)
    parser.add_argument("--local_rank", type=int, default=-1)
    parser.add_argument("--node_rank", type=int, default=0)
    parser.add_argument("--max_instr_len", type=int, default=512)
    parser.add_argument("--basepath", type=str, required=True)
    parser.add_argument("--connectivity_dir", type=str, required=True)
    parser.add_argument("--env_names", type=str, required=True)
    parser.add_argument("--val_seen_anno_paths", type=str, default="")
    parser.add_argument("--val_unseen_anno_paths", type=str, default="")
    parser.add_argument("--test_anno_paths", type=str, default="")
    parser.add_argument("--batch_size", type=int, default=8)
    parser.add_argument("--max_action_len", type=int, default=50)
    parser.add_argument("--output_path", type=str, required=True)
    parser.add_argument("--nav_resume_file", type=str, required=True)
    parser.add_argument("--qg_resume_file", type=str, required=True)
    parser.add_argument("--ag_resume_file", type=str, required=True)
    parser.add_argument("--loc_resume_file", type=str, required=True)
    parser.add_argument("--qa_clip_tokenizer_path", type=str, required=True)
    parser.add_argument("--ag_max_answer_seen_path", type=int, default=20)
    parser.add_argument("--wta_mode", type=str, default="ctc_0.7_2")
    parser.add_argument("--nav_act_visited_nodes", action="store_true")
    parser.add_argument("--benchmark", type=str, default="dialnav")
    parser.add_argument("--success_margin", type=float, default=0.0)
    parser.add_argument("--error_margin", type=float, default=3.0)
    parser.add_argument("--temporal_weight", type=float, default=0.5)
    parser.add_argument("--temporal_top_k", type=int, default=5)
    return parser.parse_args()
